const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const fromKey=k=>{const[y,m,d]=k.split('-').map(Number);return new Date(y,m-1,d)};
export class StayCalendar{
 constructor(onChange){this.month=new Date(2026,9,1);this.start='2026-10-18';this.end='2026-10-23';this.onChange=onChange}
 get nights(){return this.start&&this.end?Math.round((fromKey(this.end)-fromKey(this.start))/86400000):0}
 render(){for(const el of document.querySelectorAll('[data-calendar],#calendar-inline')){el.innerHTML=`<div class="calendar-controls"><button aria-label="Previous month">‹</button><button aria-label="Next month">›</button></div><div class="months">${[0,1].map(o=>this.renderMonth(new Date(this.month.getFullYear(),this.month.getMonth()+o,1))).join('')}</div><div class="calendar-bottom"><span class="keyboard-help"><img src="assets/svg-30.svg" alt=""></span><button class="text-link">Clear dates</button></div>`}}
 renderMonth(month){let year=month.getFullYear(),m=month.getMonth(),last=new Date(year,m+1,0).getDate();let blanks='<span></span>'.repeat(month.getDay());return `<div class="month"><h3>${month.toLocaleDateString('en-GB',{month:'long',year:'numeric'})}</h3><div class="weekdays">${['S','M','T','W','T','F','S'].map(d=>`<span>${d}</span>`).join('')}</div><div class="days">${blanks}${Array.from({length:last},(_,i)=>{let d=new Date(year,m,i+1),key=dateKey(d),selected=key===this.start||key===this.end,within=this.start&&this.end&&key>this.start&&key<this.end;return `<span class="day ${selected?'selected ':''}${within?'in-range ':''}">${i+1}</span>`}).join('')}</div></div>`}
 choose(key){if(!this.start||this.end||key<=this.start){this.start=key;this.end=null}else this.end=key;this.render();this.update()}
 shift(n){this.month=new Date(this.month.getFullYear(),this.month.getMonth()+n,1);this.render()}
 clear(){this.start=null;this.end=null;this.render();this.update()}
 update(){const n=this.nights;const fmt=k=>k?fromKey(k).toLocaleDateString('en-US'):'Add date';document.querySelectorAll('[data-checkin]').forEach(e=>e.textContent=fmt(this.start));document.querySelectorAll('[data-checkout]').forEach(e=>e.textContent=fmt(this.end));document.querySelectorAll('[data-nights]').forEach(e=>e.textContent=n||'—');document.querySelector('#stay-title').textContent=n?`${n} nights in Candolim`:'Select your dates';document.querySelector('#stay-dates').textContent=this.start?(fromKey(this.start).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})+(this.end?' - '+fromKey(this.end).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):' - Add checkout')):'Add your travel dates for exact pricing';const price=n?`₹${Math.round(28499*n/5).toLocaleString('en-IN')}`:'Add dates';document.querySelector('.price>.text-link').textContent=price;document.querySelector('[data-nav-price]').textContent=price;this.onChange?.()}
}
